{
  "handle": "resource-sharing-a",
  "name": "A",
  "description": "Owns the resource server, resource, and actions being shared in this demo.",
  "parent": null
}

{
  "handle": "resource-sharing-b",
  "name": "B",
  "description": "A Root organization unit with no relationship to A's resource server until shared.",
  "parent": null
}

{
  "name": "Booking System",
  "description": "Owned by A. Its Bookings resource and Refunds resource are shared, or withheld, to B at increasing granularity through this collection.",
  "identifier": "https://api.example.com/resource-sharing-booking",
  "ouId": "{{aOuId}}"
}

{
  "name": "Refunds",
  "handle": "refunds",
  "description": "Deliberately excluded from every share in this collection, so it stands in for 'a permission this organization unit can never see' in the write-time defense-in-depth negative tests.",
  "parent": null
}

{
  "name": "Booking App",
  "description": "An m2m application belonging to B, assigned to the booking-ops role below.",
  "ouId": "{{bOuId}}",
  "type": "m2m",
  "inboundAuthConfig": [
    {
      "type": "oauth2",
      "config": {
        "grantTypes": [
          "client_credentials"
        ],
        "tokenEndpointAuthMethod": "client_secret_basic",
        "scopes": [
          "bookings:view",
          "bookings:create",
          "bookings:cancel"
        ]
      }
    }
  ]
}

{
  "name": "booking-ops",
  "description": "Owned directly by B. Both requested permissions pass the write-time visibility check because the cascade share in '01' made both view and create visible to B at the time this role is created.",
  "ouId": "{{bOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{resourceServerId}}",
      "permissions": [
        "{{permissionView}}",
        "{{permissionCreate}}"
      ]
    }
  ],
  "assignments": [
    {
      "type": "app",
      "id": "{{bookingAppId}}"
    }
  ]
}

{
  "name": "booking-ops",
  "description": "Re-adding create after the reshare. The unshare removed it from this role outright, so restoring visibility does not bring it back: only this explicit update does, and it succeeds now because the action is visible to B again. The identical request would have been rejected with ROL-1025 while the action was still unshared.",
  "ouId": "{{bOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{resourceServerId}}",
      "permissions": [
        "{{permissionView}}",
        "{{permissionCreate}}"
      ]
    }
  ]
}

{
  "name": "Root Access App",
  "description": "An m2m application in B, assigned to a role that carries only the bare deployment root permission.",
  "ouId": "{{bOuId}}",
  "type": "m2m",
  "inboundAuthConfig": [
    {
      "type": "oauth2",
      "config": {
        "grantTypes": [
          "client_credentials"
        ],
        "tokenEndpointAuthMethod": "client_secret_basic",
        "scopes": [
          "{{rootPermission}}"
        ]
      }
    }
  ]
}

{
  "name": "root-access",
  "description": "Carries only the literal deployment root permission. B has, and will ever have, no grant at all for the System resource server: the root permission is a categorical bypass, never itself subject to a share/unshare call.",
  "ouId": "{{bOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{systemResourceServerId}}",
      "permissions": [
        "{{rootPermission}}"
      ]
    }
  ],
  "assignments": [
    {
      "type": "app",
      "id": "{{rootAccessAppId}}"
    }
  ]
}

{
  "name": "resource-sharing-scoped-admin-manage",
  "description": "Scoped admin client owned by B, used to mint system:resource-servers-scoped tokens. Also declares an unrelated scope (system:group) so a token holding neither resource-servers scope can be minted from the same client.",
  "ouId": "{{bOuId}}",
  "type": "m2m",
  "inboundAuthConfig": [
    {
      "type": "oauth2",
      "config": {
        "grantTypes": [
          "client_credentials"
        ],
        "tokenEndpointAuthMethod": "client_secret_basic",
        "scopes": [
          "system:resource-servers",
          "system:group"
        ],
        "token": {
          "accessToken": {
            "userConfig": {
              "validityPeriod": 3600
            },
            "clientConfig": {
              "attributes": [
                "sub_type",
                "ouId"
              ]
            }
          },
          "idToken": {
            "validityPeriod": 3600,
            "responseType": "JWT"
          },
          "refreshToken": {
            "validityPeriod": 86400
          }
        }
      }
    }
  ]
}

{
  "name": "resource-sharing-scoped-admin-view",
  "description": "Scoped admin client owned by B, used to mint system:resource-servers:view-scoped tokens.",
  "ouId": "{{bOuId}}",
  "type": "m2m",
  "inboundAuthConfig": [
    {
      "type": "oauth2",
      "config": {
        "grantTypes": [
          "client_credentials"
        ],
        "tokenEndpointAuthMethod": "client_secret_basic",
        "scopes": [
          "system:resource-servers:view"
        ],
        "token": {
          "accessToken": {
            "userConfig": {
              "validityPeriod": 3600
            },
            "clientConfig": {
              "attributes": [
                "sub_type",
                "ouId"
              ]
            }
          },
          "idToken": {
            "validityPeriod": 3600,
            "responseType": "JWT"
          },
          "refreshToken": {
            "validityPeriod": 86400
          }
        }
      }
    }
  ]
}

{
  "name": "System Resource Servers Manager",
  "description": "Carries the system:resource-servers permission and is owned by B, the same organization unit the scoped applications live in. Two things have to hold for this to work, and both come from the System resource server being shared deployment-wide at bootstrap (grants: allOus). First, the write-time visibility check accepts the permission because B can see the System resource server. Second, and easy to miss, the assignment below is recorded against B, so the OU-scoped permission resolution at token issuance finds it: a role owned by the default organization unit would record its assignment there instead, and the token, whose ouId claim is B, would come back with no scopes at all.",
  "ouId": "{{bOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{systemResourceServerId}}",
      "permissions": [
        "system:resource-servers"
      ]
    }
  ]
}

{
  "name": "System Resource Servers Viewer",
  "description": "Carries the read-only system:resource-servers:view permission; assigned to an m2m application that should only ever list and read resource servers, resources, and actions, never create, update, delete, or share them. Owned by B for the same two reasons as the manager role above.",
  "ouId": "{{bOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{systemResourceServerId}}",
      "permissions": [
        "system:resource-servers:view"
      ]
    }
  ]
}

{
  "name": "Confinement Control RS",
  "description": "Owned by A and never shared to anyone. Exists so the scoped listing below has something that genuinely must not appear. The System resource server cannot play that role: it is shared deployment-wide on purpose.",
  "ouId": "{{aOuId}}",
  "identifier": "https://resource-sharing-demo.example.com/confinement-control"
}

{
  "name": "Scoped Admin Demo Server",
  "description": "Created by a system:resource-servers token in its own organization unit.",
  "identifier": "https://api.example.com/resource-sharing-scoped-admin-demo",
  "ouId": "{{bOuId}}"
}

{
  "name": "Scoped Admin Demo Server",
  "description": "Updated by a system:resource-servers token that owns this resource server.",
  "identifier": "https://api.example.com/resource-sharing-scoped-admin-demo",
  "ouId": "{{bOuId}}"
}
